-- Assessments, their questions and their windows.
-- Tables: asmt_lst_t, asmt_qstn_rel_t, asmt_wndw_lst_t
-- Generated by server/scripts/export-sql.mjs from the migrated database. Run the files in numeric order on an empty database.

BEGIN;

CREATE TABLE public.asmt_lst_t (
    asmt_id text NOT NULL,
    college_id text NOT NULL,
    course_id text,
    asmt_type_cd public."AssessmentType" DEFAULT 'QUIZ'::public."AssessmentType" NOT NULL,
    asmt_ttl text NOT NULL,
    instructions_tx text DEFAULT ''::text NOT NULL,
    duration_min_ct integer,
    pass_pct integer DEFAULT 40 NOT NULL,
    max_attempts_ct integer DEFAULT 1 NOT NULL,
    attempt_strategy_cd public."AttemptStrategy" DEFAULT 'BEST'::public."AttemptStrategy" NOT NULL,
    shuffle_qstn_in smallint DEFAULT 0 NOT NULL,
    shuffle_optn_in smallint DEFAULT 0 NOT NULL,
    result_visibility_cd public."ResultVisibility" DEFAULT 'IMMEDIATE'::public."ResultVisibility" NOT NULL,
    results_published_in smallint DEFAULT 0 NOT NULL,
    status_cd public."AssessmentStatus" DEFAULT 'DRAFT'::public."AssessmentStatus" NOT NULL,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    u_ts timestamp(3) without time zone,
    crte_usr_id text,
    updte_usr_id text,
    a_in smallint DEFAULT 1 NOT NULL,
    d_ts timestamp(3) without time zone,
    CONSTRAINT asmt_lst_t_flags_check CHECK (((shuffle_qstn_in = ANY (ARRAY[0, 1])) AND (shuffle_optn_in = ANY (ARRAY[0, 1])) AND (results_published_in = ANY (ARRAY[0, 1])) AND (a_in = ANY (ARRAY[0, 1])))),
    CONSTRAINT asmt_lst_t_values_check CHECK ((((pass_pct >= 0) AND (pass_pct <= 100)) AND ((max_attempts_ct >= 1) AND (max_attempts_ct <= 20)) AND ((duration_min_ct IS NULL) OR ((duration_min_ct >= 1) AND (duration_min_ct <= 600)))))
);

CREATE TABLE public.asmt_qstn_rel_t (
    asmt_qstn_id text NOT NULL,
    asmt_id text NOT NULL,
    qstn_id text NOT NULL,
    sqnce_id integer DEFAULT 0 NOT NULL,
    marks_override_ct double precision
);

CREATE TABLE public.asmt_wndw_lst_t (
    asmt_wndw_id text NOT NULL,
    asmt_id text NOT NULL,
    chrt_id text,
    opens_ts timestamp(3) without time zone NOT NULL,
    closes_ts timestamp(3) without time zone NOT NULL,
    extra_time_min_ct integer DEFAULT 0 NOT NULL,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    u_ts timestamp(3) without time zone,
    crte_usr_id text,
    updte_usr_id text,
    a_in smallint DEFAULT 1 NOT NULL,
    d_ts timestamp(3) without time zone,
    CONSTRAINT asmt_wndw_lst_t_a_in_check CHECK ((a_in = ANY (ARRAY[0, 1]))),
    CONSTRAINT asmt_wndw_lst_t_times_check CHECK (((closes_ts > opens_ts) AND ((extra_time_min_ct >= 0) AND (extra_time_min_ct <= 600))))
);

ALTER TABLE ONLY public.asmt_lst_t
    ADD CONSTRAINT asmt_lst_t_pkey PRIMARY KEY (asmt_id);

ALTER TABLE ONLY public.asmt_qstn_rel_t
    ADD CONSTRAINT asmt_qstn_rel_t_pkey PRIMARY KEY (asmt_qstn_id);

ALTER TABLE ONLY public.asmt_wndw_lst_t
    ADD CONSTRAINT asmt_wndw_lst_t_pkey PRIMARY KEY (asmt_wndw_id);

CREATE INDEX asmt_lst_t_college_id_idx ON public.asmt_lst_t USING btree (college_id);

CREATE UNIQUE INDEX asmt_qstn_rel_t_asmt_id_qstn_id_key ON public.asmt_qstn_rel_t USING btree (asmt_id, qstn_id);

CREATE INDEX asmt_wndw_lst_t_asmt_id_idx ON public.asmt_wndw_lst_t USING btree (asmt_id);

CREATE TRIGGER asmt_lst_t_audit_timestamps BEFORE UPDATE ON public.asmt_lst_t FOR EACH ROW EXECUTE FUNCTION public.campus_set_audit_timestamps();

CREATE TRIGGER asmt_wndw_lst_t_audit_timestamps BEFORE UPDATE ON public.asmt_wndw_lst_t FOR EACH ROW EXECUTE FUNCTION public.campus_set_audit_timestamps();

-- Foreign keys
ALTER TABLE ONLY public.asmt_qstn_rel_t
    ADD CONSTRAINT asmt_qstn_rel_t_asmt_id_fkey FOREIGN KEY (asmt_id) REFERENCES public.asmt_lst_t(asmt_id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE ONLY public.asmt_qstn_rel_t
    ADD CONSTRAINT asmt_qstn_rel_t_qstn_id_fkey FOREIGN KEY (qstn_id) REFERENCES public.qstn_lst_t(qstn_id) ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE ONLY public.asmt_wndw_lst_t
    ADD CONSTRAINT asmt_wndw_lst_t_asmt_id_fkey FOREIGN KEY (asmt_id) REFERENCES public.asmt_lst_t(asmt_id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE ONLY public.asmt_wndw_lst_t
    ADD CONSTRAINT asmt_wndw_lst_t_chrt_id_fkey FOREIGN KEY (chrt_id) REFERENCES public.chrt_lst_t(chrt_id) ON UPDATE CASCADE ON DELETE SET NULL;

COMMIT;
